{
  "extends": "next/core-web-vitals"
}

import Link from "next/link";
import { redirect } from "next/navigation";

import { SignOutButton } from "@/components/auth/sign-out-button";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { getCurrentProfile } from "@/lib/auth";
import { getOrdersForUser } from "@/lib/repositories/orders";
import { formatPrice } from "@/lib/utils";

export const metadata = { title: "My Account" };

export default async function AccountPage() {
  const profile = await getCurrentProfile();
  if (!profile) redirect("/login?redirect=/account");

  const orders = await getOrdersForUser(profile.id);

  return (
    <div className="container py-12">
      <div className="mb-10 flex flex-wrap items-end justify-between gap-4">
        <div>
          <span className="eyebrow">My Account</span>
          <h1 className="mt-2 font-serif text-4xl tracking-tight">
            {profile.full_name || "Welcome"}
          </h1>
          <p className="mt-1 text-sm text-muted-foreground">{profile.email}</p>
        </div>
        <div className="flex items-center gap-3">
          {profile.role === "admin" && (
            <Button asChild variant="gold" size="sm">
              <Link href="/admin/dashboard">Admin Panel</Link>
            </Button>
          )}
          <SignOutButton />
        </div>
      </div>

      <h2 className="mb-6 font-serif text-2xl">Order History</h2>

      {orders.length === 0 ? (
        <div className="border border-border p-10 text-center">
          <p className="text-muted-foreground">
            You haven&apos;t placed any orders yet.
          </p>
          <Button asChild className="mt-4">
            <Link href="/shop">Start shopping</Link>
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          {orders.map((order) => (
            <div key={order.id} className="border border-border p-6">
              <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
                <div>
                  <p className="text-sm font-medium tracking-wide">
                    {order.order_number}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {new Date(order.created_at).toLocaleDateString(undefined, {
                      year: "numeric",
                      month: "long",
                      day: "numeric",
                    })}
                  </p>
                </div>
                <div className="flex items-center gap-3">
                  <Badge variant="outline">{order.order_status}</Badge>
                  <span className="font-serif text-lg">
                    {formatPrice(order.total_amount)}
                  </span>
                </div>
              </div>

              <div className="mt-6 space-y-2 border-t border-border pt-4">
                {order.items.map((item) => (
                  <div
                    key={item.id}
                    className="flex justify-between text-sm text-muted-foreground"
                  >
                    <span>
                      {item.product?.title ?? "Item"}
                      {item.variant && ` — Size ${item.variant.size}`} ×{" "}
                      {item.quantity}
                    </span>
                    <span>{formatPrice(item.unit_price * item.quantity)}</span>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useMemo, useState } from "react";

import { zodResolver } from "@hookform/resolvers/zod";
import { ChevronLeft, CreditCard, Loader2, MapPin, Truck } from "lucide-react";
import { Controller, useForm } from "react-hook-form";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  getShippingFee,
  PAKISTAN_CITIES,
  SHIPPING_KARACHI,
  SHIPPING_OTHER,
} from "@/constants/shop";
import { placeOrder } from "@/lib/actions/orders";
import { cn, formatPrice } from "@/lib/utils";
import { checkoutSchema, type CheckoutFormValues } from "@/lib/validators/checkout";
import { selectSubtotal, useCart } from "@/store/cart";

export default function CheckoutPage() {
  const router = useRouter();
  const { items, clear } = useCart();
  const [mounted, setMounted] = useState(false);
  const [step, setStep] = useState<1 | 2>(1);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => setMounted(true), []);

  const {
    register,
    handleSubmit,
    trigger,
    watch,
    setValue,
    control,
    formState: { errors },
  } = useForm<CheckoutFormValues>({
    resolver: zodResolver(checkoutSchema),
    defaultValues: {
      country: "Pakistan",
      city: "Karachi",
      cityOther: "",
      paymentMethod: "COD",
    },
  });

  const paymentMethod = watch("paymentMethod");
  const city = watch("city");
  const cityOther = watch("cityOther");

  const resolvedCity = useMemo(() => {
    if (city === "Other") return (cityOther ?? "").trim();
    return city?.trim() ?? "";
  }, [city, cityOther]);

  const subtotal = mounted ? selectSubtotal(items) : 0;
  const shipping = getShippingFee(resolvedCity || "Karachi");
  const total = subtotal + shipping;
  const isKarachi = resolvedCity.toLowerCase() === "karachi";

  const goToPayment = async () => {
    const fields: (keyof CheckoutFormValues)[] = [
      "customerName",
      "customerEmail",
      "customerPhone",
      "address",
      "city",
      "postalCode",
      "country",
    ];
    if (city === "Other") fields.push("cityOther");
    const valid = await trigger(fields);
    if (valid) setStep(2);
  };

  const onSubmit = async (values: CheckoutFormValues) => {
    if (values.paymentMethod === "Card") {
      toast.error("Card payments are coming soon. Please choose Cash on Delivery.");
      return;
    }
    if (items.length === 0) {
      toast.error("Your bag is empty");
      return;
    }

    setSubmitting(true);
    const result = await placeOrder({
      ...values,
      items: items.map((i) => ({ variantId: i.variantId, quantity: i.quantity })),
    });
    setSubmitting(false);

    if (!result.success) {
      toast.error(result.error ?? "Something went wrong");
      return;
    }

    toast.success("Order placed successfully!", {
      description: "Opening your order details…",
    });
    clear();
    router.push(`/order-success/${result.orderId}`);
  };

  if (mounted && items.length === 0) {
    return (
      <div className="container flex min-h-[60vh] flex-col items-center justify-center gap-4 text-center">
        <h1 className="font-serif text-3xl">Your bag is empty</h1>
        <p className="text-muted-foreground">
          Add some pieces before proceeding to checkout.
        </p>
        <Button asChild>
          <Link href="/shop">Continue shopping</Link>
        </Button>
      </div>
    );
  }

  return (
    <div className="container max-w-full overflow-x-hidden py-12">
      <h1 className="mb-8 font-serif text-4xl tracking-tight">Checkout</h1>

      <div className="grid gap-12 lg:grid-cols-[1fr_400px]">
        <form onSubmit={handleSubmit(onSubmit)} className="min-w-0 space-y-8">
          <div className="flex items-center gap-4 text-xs uppercase tracking-widest">
            <span className={cn(step === 1 ? "text-charcoal" : "text-muted-foreground")}>
              1. Shipping
            </span>
            <span className="h-px w-8 bg-border" />
            <span className={cn(step === 2 ? "text-charcoal" : "text-muted-foreground")}>
              2. Payment
            </span>
          </div>

          {step === 1 && (
            <div className="space-y-6">
              <h2 className="font-serif text-xl">Contact &amp; Shipping</h2>

              <div className="flex items-start gap-3 border border-border bg-offwhite p-4 text-sm">
                <MapPin className="mt-0.5 h-4 w-4 shrink-0 text-gold" />
                <div>
                  <p className="font-medium">Delivery location &amp; shipping</p>
                  <p className="mt-1 text-xs text-muted-foreground">
                    Karachi: {formatPrice(SHIPPING_KARACHI)} · Other cities:{" "}
                    {formatPrice(SHIPPING_OTHER)}
                  </p>
                </div>
              </div>

              <div className="grid gap-4 sm:grid-cols-2">
                <Field label="Full name" error={errors.customerName?.message}>
                  <Input {...register("customerName")} placeholder="Your full name" />
                </Field>
                <Field label="Email" error={errors.customerEmail?.message}>
                  <Input
                    {...register("customerEmail")}
                    type="email"
                    placeholder="you@example.com"
                  />
                </Field>
                <Field label="Phone" error={errors.customerPhone?.message}>
                  <Input {...register("customerPhone")} placeholder="03XX XXXXXXX" />
                </Field>
                <Field label="Country" error={errors.country?.message}>
                  <Input {...register("country")} readOnly className="bg-muted/40" />
                </Field>

                <Field label="City / Location" error={errors.city?.message}>
                  <Controller
                    control={control}
                    name="city"
                    render={({ field }) => (
                      <Select
                        value={field.value}
                        onValueChange={(value) => {
                          field.onChange(value);
                          if (value !== "Other") setValue("cityOther", "");
                        }}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Select your city" />
                        </SelectTrigger>
                        <SelectContent>
                          {PAKISTAN_CITIES.map((c) => (
                            <SelectItem key={c} value={c}>
                              {c}
                              {c === "Karachi" ? ` · ${formatPrice(SHIPPING_KARACHI)}` : ""}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                </Field>

                {city === "Other" ? (
                  <Field label="Enter your city" error={errors.cityOther?.message}>
                    <Input
                      {...register("cityOther")}
                      placeholder="e.g. Abbottabad"
                    />
                  </Field>
                ) : (
                  <Field label="Postal code" error={errors.postalCode?.message}>
                    <Input {...register("postalCode")} placeholder="75500" />
                  </Field>
                )}

                <div className="sm:col-span-2">
                  <Field label="Street address" error={errors.address?.message}>
                    <Input
                      {...register("address")}
                      placeholder="House / street / area"
                    />
                  </Field>
                </div>

                {city === "Other" && (
                  <Field label="Postal code" error={errors.postalCode?.message}>
                    <Input {...register("postalCode")} placeholder="75500" />
                  </Field>
                )}
              </div>

              <div className="rounded-none border border-gold/30 bg-gold/5 px-4 py-3 text-sm">
                Shipping to{" "}
                <span className="font-medium">
                  {resolvedCity || "your city"}
                </span>
                :{" "}
                <span className="font-medium text-gold-dark">
                  {formatPrice(shipping)}
                </span>
                {!isKarachi && resolvedCity && (
                  <span className="text-muted-foreground">
                    {" "}
                    (outside Karachi)
                  </span>
                )}
              </div>

              <Button type="button" size="lg" onClick={goToPayment}>
                Continue to payment
              </Button>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6">
              <button
                type="button"
                onClick={() => setStep(1)}
                className="flex items-center gap-1 text-xs uppercase tracking-widest text-muted-foreground hover:text-charcoal"
              >
                <ChevronLeft className="h-3 w-3" /> Back to shipping
              </button>
              <h2 className="font-serif text-xl">Payment Method</h2>

              <div className="space-y-3">
                <button
                  type="button"
                  onClick={() => setValue("paymentMethod", "COD")}
                  className={cn(
                    "flex w-full items-center gap-3 border p-4 text-left transition-colors",
                    paymentMethod === "COD"
                      ? "border-charcoal bg-secondary"
                      : "border-border hover:border-charcoal"
                  )}
                >
                  <Truck className="h-5 w-5" />
                  <div>
                    <p className="text-sm font-medium">Cash on Delivery</p>
                    <p className="text-xs text-muted-foreground">
                      Pay in cash when your order arrives.
                    </p>
                  </div>
                </button>

                <button
                  type="button"
                  onClick={() => setValue("paymentMethod", "Card")}
                  className={cn(
                    "flex w-full items-center gap-3 border p-4 text-left transition-colors",
                    paymentMethod === "Card"
                      ? "border-charcoal bg-secondary"
                      : "border-border hover:border-charcoal"
                  )}
                >
                  <CreditCard className="h-5 w-5" />
                  <div>
                    <p className="text-sm font-medium">Card / Online Payment</p>
                    <p className="text-xs text-muted-foreground">
                      Secure online payment.
                    </p>
                  </div>
                </button>

                {paymentMethod === "Card" && (
                  <div className="border border-gold/40 bg-gold/5 p-4 text-xs text-gold-dark">
                    Online card payments are coming soon. For now, please select
                    Cash on Delivery to complete your order.
                  </div>
                )}
              </div>

              <Button
                type="submit"
                size="lg"
                className="w-full"
                disabled={submitting || paymentMethod === "Card"}
              >
                {submitting && <Loader2 className="h-4 w-4 animate-spin" />}
                {submitting
                  ? "Placing order..."
                  : `Place order · ${formatPrice(total)}`}
              </Button>
            </div>
          )}
        </form>

        <aside className="h-fit min-w-0 border border-border bg-offwhite p-6 lg:sticky lg:top-24">
          <h2 className="mb-4 font-serif text-lg">Order Summary</h2>
          <div className="max-h-72 space-y-4 overflow-y-auto">
            {mounted &&
              items.map((item) => (
                <div key={item.variantId} className="flex gap-3">
                  <div className="relative h-16 w-14 shrink-0 overflow-hidden bg-muted">
                    {item.image && (
                      <Image
                        src={item.image}
                        alt={item.title}
                        fill
                        sizes="56px"
                        className="object-cover"
                      />
                    )}
                    <span className="absolute -right-1 -top-1 flex h-5 w-5 items-center justify-center rounded-full bg-charcoal text-[10px] text-white">
                      {item.quantity}
                    </span>
                  </div>
                  <div className="flex min-w-0 flex-1 flex-col justify-center">
                    <p className="truncate text-sm font-medium">{item.title}</p>
                    <p className="text-xs text-muted-foreground">
                      Size {item.size}
                    </p>
                  </div>
                  <span className="shrink-0 self-center text-sm">
                    {formatPrice(item.unitPrice * item.quantity)}
                  </span>
                </div>
              ))}
          </div>

          <div className="mt-6 space-y-2 border-t border-border pt-4 text-sm">
            <div className="flex justify-between">
              <span className="text-muted-foreground">Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="flex justify-between gap-2">
              <span className="text-muted-foreground">
                Shipping
                {resolvedCity ? (
                  <span className="block text-[11px]">to {resolvedCity}</span>
                ) : null}
              </span>
              <span className="text-right">{formatPrice(shipping)}</span>
            </div>
            <div className="flex justify-between border-t border-border pt-3 font-serif text-lg">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
}

function Field({
  label,
  error,
  children,
}: {
  label: string;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-1.5">
      <Label>{label}</Label>
      {children}
      {error && <p className="text-xs text-destructive">{error}</p>}
    </div>
  );
}

import { AnnouncementBar } from "@/components/layout/announcement-bar";
import { Footer } from "@/components/layout/footer";
import { Header } from "@/components/layout/header";
import { CartDrawer } from "@/components/cart/cart-drawer";
import { getCategories } from "@/lib/repositories/categories";

export default async function StoreLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const categories = await getCategories();

  return (
    <div className="flex min-h-screen flex-col overflow-x-hidden">
      <AnnouncementBar />
      <Header
        categories={categories.map((c) => ({ name: c.name, slug: c.slug }))}
      />
      <main className="min-w-0 flex-1">{children}</main>
      <Footer />
      <CartDrawer />
    </div>
  );
}

import { Suspense } from "react";

import { AuthForm } from "@/components/auth/auth-form";

export const metadata = { title: "Sign In" };

export default function LoginPage() {
  return (
    <Suspense>
      <AuthForm mode="login" />
    </Suspense>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";

import { CheckCircle2, Package } from "lucide-react";

import { OrderCelebration } from "@/components/order/order-celebration";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { getOrderForConfirmation } from "@/lib/repositories/orders";
import { formatPrice } from "@/lib/utils";

export const metadata = { title: "Order Details" };

export default async function OrderSuccessPage({
  params,
}: {
  params: { orderId: string };
}) {
  const order = await getOrderForConfirmation(params.orderId);
  if (!order) notFound();

  const shippingFee =
    typeof order.shipping_address.shipping_fee === "number"
      ? order.shipping_address.shipping_fee
      : null;
  const itemsSubtotal = order.items.reduce(
    (sum, item) => sum + Number(item.unit_price) * item.quantity,
    0
  );

  return (
    <div className="container max-w-3xl overflow-x-hidden py-12 sm:py-16">
      <OrderCelebration />

      <div className="mb-10 text-center">
        <CheckCircle2 className="mx-auto h-14 w-14 text-gold" />
        <p className="eyebrow mt-4 text-gold">Order placed successfully</p>
        <h1 className="mt-2 font-serif text-3xl tracking-tight sm:text-4xl">
          Your order details
        </h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Confirmation sent to {order.customer_email}
        </p>
        <p className="mt-4 inline-flex items-center gap-2 border border-border px-4 py-2 text-sm">
          <Package className="h-4 w-4 text-gold" />
          Order{" "}
          <span className="font-medium tracking-wide">{order.order_number}</span>
        </p>
      </div>

      <div className="border border-border bg-white p-6 sm:p-8">
        <h2 className="eyebrow mb-4">Items ordered</h2>
        <div className="space-y-4">
          {order.items.map((item) => (
            <div
              key={item.id}
              className="flex items-start justify-between gap-4 border-b border-border pb-4 last:border-0 last:pb-0"
            >
              <div>
                <p className="text-sm font-medium">
                  {item.product?.title ?? "Item"}
                </p>
                <p className="text-xs text-muted-foreground">
                  {item.variant ? `Size ${item.variant.size} · ` : ""}
                  Qty {item.quantity}
                </p>
              </div>
              <span className="shrink-0 text-sm">
                {formatPrice(Number(item.unit_price) * item.quantity)}
              </span>
            </div>
          ))}
        </div>

        <Separator className="my-8" />

        <div className="grid gap-8 sm:grid-cols-2">
          <div>
            <h3 className="eyebrow mb-2">Shipping to</h3>
            <p className="text-sm font-medium">{order.customer_name}</p>
            <p className="mt-1 text-sm text-muted-foreground">
              {order.shipping_address.address}
              <br />
              {order.shipping_address.city}, {order.shipping_address.postal_code}
              <br />
              {order.shipping_address.country}
            </p>
            {order.customer_phone && (
              <p className="mt-2 text-xs text-muted-foreground">
                Phone: {order.customer_phone}
              </p>
            )}
          </div>

          <div className="sm:text-right">
            <h3 className="eyebrow mb-2">Payment &amp; total</h3>
            <p className="text-sm">
              {order.payment_method === "COD"
                ? "Cash on Delivery"
                : "Card / Online"}
            </p>
            <div className="mt-4 space-y-1 text-sm">
              <div className="flex justify-between gap-4 sm:justify-end sm:gap-8">
                <span className="text-muted-foreground">Subtotal</span>
                <span>{formatPrice(itemsSubtotal)}</span>
              </div>
              {shippingFee != null && (
                <div className="flex justify-between gap-4 sm:justify-end sm:gap-8">
                  <span className="text-muted-foreground">
                    Shipping ({order.shipping_address.city})
                  </span>
                  <span>{formatPrice(shippingFee)}</span>
                </div>
              )}
              <div className="flex justify-between gap-4 border-t border-border pt-2 font-serif text-xl sm:justify-end sm:gap-8">
                <span>Total</span>
                <span>{formatPrice(order.total_amount)}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-10 flex flex-wrap justify-center gap-3">
        <Button asChild variant="outline">
          <Link href="/shop">Continue shopping</Link>
        </Button>
        <Button asChild>
          <Link href="/account">View order history</Link>
        </Button>
      </div>
    </div>
  );
}

import Link from "next/link";

import { CategoryGrid } from "@/components/home/category-grid";
import { EditorialBanner } from "@/components/home/editorial-banner";
import { Hero } from "@/components/home/hero";
import { BlurFade } from "@/components/motion/blur-fade";
import { Reveal } from "@/components/motion/reveal";
import { ProductGrid } from "@/components/product/product-grid";
import { SectionHeading } from "@/components/ui/section-heading";
import { Button } from "@/components/ui/button";
import { getCategories } from "@/lib/repositories/categories";
import {
  getFeaturedProducts,
  getNewArrivals,
} from "@/lib/repositories/products";

export const revalidate = 60;

export default async function HomePage() {
  const [categories, featured, newArrivals] = await Promise.all([
    getCategories(),
    getFeaturedProducts(4),
    getNewArrivals(8),
  ]);

  return (
    <>
      <Hero />

      {/* Featured categories */}
      <section className="container py-20">
        <Reveal>
          <SectionHeading
            eyebrow="Curated Edits"
            title="Shop by Category"
            linkHref="/shop"
            linkLabel="View all"
          />
        </Reveal>
        <CategoryGrid categories={categories.slice(0, 4)} />
      </section>

      {/* New arrivals */}
      <section className="bg-offwhite py-20">
        <div className="container">
          <Reveal>
            <SectionHeading
              eyebrow="Just In"
              title="New Arrivals"
              linkHref="/shop?sort=newest"
              linkLabel="Shop new in"
            />
          </Reveal>
          <ProductGrid products={newArrivals} />
        </div>
      </section>

      {/* Shop the look / editorial */}
      <EditorialBanner />

      {/* Featured grid */}
      {featured.length > 0 && (
        <section className="container pb-24">
          <Reveal>
            <SectionHeading
              eyebrow="Editor's Picks"
              title="Featured Pieces"
              align="center"
            />
          </Reveal>
          <ProductGrid products={featured} />
        </section>
      )}

      {/* Soft CTA strip */}
      <section className="border-y border-border bg-offwhite py-16">
        <div className="container flex flex-col items-center text-center">
          <BlurFade>
            <span className="eyebrow">Private Preview</span>
            <h2 className="mt-3 font-serif text-3xl tracking-tight sm:text-4xl">
              New drops, every week
            </h2>
            <p className="mt-4 max-w-md text-sm text-muted-foreground">
              Explore the latest branded pieces curated for Naz&apos;s Collection —
              limited sizes, fast shipping across Pakistan.
            </p>
            <Button asChild variant="gold" size="lg" className="mt-8">
              <Link href="/shop?sort=newest">Browse New In</Link>
            </Button>
          </BlurFade>
        </div>
      </section>
    </>
  );
}

import { notFound } from "next/navigation";

import { ProductDetail } from "@/components/product/product-detail";
import { ProductGrid } from "@/components/product/product-grid";
import { SectionHeading } from "@/components/ui/section-heading";
import { getNewArrivals, getProductBySlug } from "@/lib/repositories/products";

export const revalidate = 60;

export async function generateMetadata({
  params,
}: {
  params: { slug: string };
}) {
  const product = await getProductBySlug(params.slug);
  if (!product) return { title: "Product not found" };
  return {
    title: product.title,
    description: product.description ?? undefined,
  };
}

export default async function ProductPage({
  params,
}: {
  params: { slug: string };
}) {
  const product = await getProductBySlug(params.slug);
  if (!product) notFound();

  const related = (await getNewArrivals(8)).filter((p) => p.id !== product.id);

  return (
    <>
      <ProductDetail product={product} />

      {related.length > 0 && (
        <section className="container border-t border-border py-16">
          <SectionHeading eyebrow="You may also like" title="Complete the Edit" />
          <ProductGrid products={related.slice(0, 4)} />
        </section>
      )}
    </>
  );
}

