export default async function AdminProductsPage() {
  const products = await getAdminProducts();

  return (
    <div className="p-6 lg:p-10">
      <div className="mb-8 flex items-center justify-between">
        <div>
          <h1 className="font-serif text-3xl tracking-tight">Products</h1>
          <p className="text-sm text-muted-foreground">
            {products.length} products in your catalog.
          </p>
        </div>
        <Button asChild>
          <Link href="/admin/products/new">
            <Plus className="h-4 w-4" /> New Product
          </Link>
        </Button>
      </div>

      <div className="border border-border bg-white">
        {products.length === 0 ? (
          <p className="p-6 text-sm text-muted-foreground">
            No products yet. Create your first product.
          </p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border text-left text-xs uppercase tracking-wide text-muted-foreground">
                  <th className="p-4">Product</th>
                  <th className="p-4">Brand</th>
                  <th className="p-4">Category</th>
                  <th className="p-4">Price</th>
                  <th className="p-4">Stock</th>
                  <th className="p-4">Status</th>
                  <th className="p-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {products.map((product) => {
                  const stock = product.variants.reduce(
                    (sum, v) => sum + v.stock_quantity,
                    0
                  );
                  return (
                    <tr
                      key={product.id}
                      className="border-b border-border align-middle last:border-0"
                    >
                      <td className="p-4">
                        <div className="flex items-center gap-3">
                          <div className="h-12 w-10 shrink-0 bg-muted" />
                          <div>
                            <div className="font-medium">{product.title}</div>
                            <div className="text-xs text-muted-foreground">
                              /{product.slug}
                              {product.weight != null
                                ? ` · ${Number(product.weight)} g`
                                : ""}
                            </div>
                          </div>
                        </div>
                      </td>
                      <td className="p-4 text-muted-foreground">
                        {product.brand_name ?? "—"}
                      </td>
                      <td className="p-4 text-muted-foreground">
                        {product.category?.name ?? "—"}
                      </td>
                      <td className="p-4">{formatPrice(product.base_price)}</td>
                      <td className="p-4">
                        <span className={stock <= 3 ? "text-destructive" : ""}>
                          {stock}
                        </span>
                      </td>
                      <td className="p-4">
                        <Badge variant={product.is_active ? "gold" : "muted"}>
                          {product.is_active ? "Active" : "Hidden"}
                        </Badge>
                      </td>
                      <td className="p-4">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            asChild
                            variant="ghost"
                            size="icon"
                            aria-label="Edit product"
                          >
                            <Link href={`/admin/products/${product.id}/edit`}>
                              <Pencil className="h-4 w-4" />
                            </Link>
                          </Button>
                          <DeleteProductButton
                            productId={product.id}
                            productTitle={product.title}
                          />
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";

import { ChevronLeft } from "lucide-react";

import { ProductForm } from "@/components/admin/product-form";
import { getCategories } from "@/lib/repositories/categories";
import { getAdminProductById } from "@/lib/repositories/admin";
import type { ProductImage, ProductVariant } from "@/lib/types";
import type { ProductFormValues } from "@/lib/validators/product";

export const metadata = { title: "Edit Product" };

export default async function EditProductPage({
  params,
}: {
  params: { id: string };
}) {
  const [product, categories] = await Promise.all([
    getAdminProductById(params.id),
    getCategories(),
  ]);

  if (!product) notFound();

  const typed = product as typeof product & {
    images: ProductImage[];
    variants: ProductVariant[];
  };

  const defaultValues: Partial<ProductFormValues> = {
    title: typed.title,
    slug: typed.slug,
    description: typed.description ?? "",
    brand_name: typed.brand_name ?? "",
    weight: typed.weight != null ? Number(typed.weight) : null,
    category_id: typed.category_id,
    base_price: Number(typed.base_price),
    discount_price: typed.discount_price ? Number(typed.discount_price) : null,
    featured: typed.featured,
    is_active: typed.is_active,
    images: [...typed.images]
      .sort((a, b) => a.display_order - b.display_order)
      .map((i) => i.image_url),
    variants: typed.variants.map((v) => ({
      size: v.size,
      stock_quantity: v.stock_quantity,
      price_override: v.price_override,
    })),
  };

  return (
    <div className="p-6 lg:p-10">
      <Link
        href="/admin/products"
        className="mb-6 inline-flex items-center gap-1 text-xs uppercase tracking-widest text-muted-foreground hover:text-charcoal"
      >
        <ChevronLeft className="h-3 w-3" /> Back to products
      </Link>
      <h1 className="mb-8 font-serif text-3xl tracking-tight">
        Edit Product
      </h1>
      <ProductForm
        categories={categories.map((c) => ({ id: c.id, name: c.name }))}
        productId={typed.id}
        defaultValues={defaultValues}
      />
    </div>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 0 0% 7%;

    --card: 0 0% 100%;
    --card-foreground: 0 0% 7%;

    --popover: 0 0% 100%;
    --popover-foreground: 0 0% 7%;

    /* Deep charcoal primary (buttons, headings) */
    --primary: 0 0% 7%;
    --primary-foreground: 0 0% 100%;

    /* Soft off-white surfaces */
    --secondary: 0 0% 98%;
    --secondary-foreground: 0 0% 7%;

    --muted: 0 0% 96%;
    --muted-foreground: 0 0% 42%;

    /* Royal metallic gold accent */
    --accent: 46 65% 52%;
    --accent-foreground: 0 0% 7%;

    --destructive: 0 72% 45%;
    --destructive-foreground: 0 0% 100%;

    /* Pale silver borders */
    --border: 0 0% 88%;
    --input: 0 0% 88%;
    --ring: 46 65% 52%;

    --radius: 0.25rem;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-feature-settings: "rlig" 1, "calt" 1;
  }
  h1,
  h2,
  h3,
  h4 {
    @apply font-serif tracking-tight;
  }
}

@layer utilities {
  /* Glassmorphism overlay used for drawers/menus */
  .glass {
    @apply bg-white/70 backdrop-blur-xl;
    -webkit-backdrop-filter: blur(20px);
  }
  .glass-dark {
    @apply bg-charcoal/80 backdrop-blur-xl;
    -webkit-backdrop-filter: blur(20px);
  }

  /* Editorial gold underline hover for links */
  .link-gold {
    @apply relative text-charcoal transition-colors hover:text-gold;
  }

  /* Thin uppercase eyebrow label */
  .eyebrow {
    @apply text-xs font-medium uppercase tracking-[0.25em] text-muted-foreground;
  }

  /* Subtle skeleton shimmer */
  .shimmer {
    @apply relative overflow-hidden bg-muted;
  }
  .shimmer::after {
    @apply absolute inset-0 -translate-x-full;
    content: "";
    background-image: linear-gradient(
      90deg,
      rgba(255, 255, 255, 0) 0,
      rgba(255, 255, 255, 0.6) 50%,
      rgba(255, 255, 255, 0) 100%
    );
    animation: shimmer 1.6s infinite;
  }
}

/* Minimal luxe scrollbar */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
::-webkit-scrollbar-thumb {
  background: #d9d9d9;
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: #c0c0c0;
}

