"use client";

import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";

import { Trash2 } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { deleteProduct } from "@/lib/actions/admin/products";

export function DeleteProductButton({
  productId,
  productTitle,
}: {
  productId: string;
  productTitle: string;
}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [isPending, startTransition] = useTransition();

  const onConfirm = () => {
    startTransition(async () => {
      const result = await deleteProduct(productId);
      if (!result.success) {
        toast.error(result.error ?? "Delete failed");
        return;
      }
      toast.success("Product deleted");
      setOpen(false);
      router.refresh();
    });
  };

  return (
    <>
      <Button
        variant="ghost"
        size="icon"
        aria-label="Delete product"
        onClick={() => setOpen(true)}
      >
        <Trash2 className="h-4 w-4 text-destructive" />
      </Button>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete product</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete &quot;{productTitle}&quot;? This
              also removes its variants and images and cannot be undone.
            </DialogDescription>
          </DialogHeader>
          <div className="flex justify-end gap-3">
            <Button variant="outline" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={onConfirm}
              disabled={isPending}
            >
              Delete
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import { useState, useTransition } from "react";

import { toast } from "sonner";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { updateOrderStatus } from "@/lib/actions/admin/orders";
import type { OrderStatus } from "@/lib/supabase/types";

const STATUSES: OrderStatus[] = [
  "pending",
  "processing",
  "shipped",
  "delivered",
  "cancelled",
];

export function OrderStatusSelect({
  orderId,
  currentStatus,
}: {
  orderId: string;
  currentStatus: OrderStatus;
}) {
  const [status, setStatus] = useState<OrderStatus>(currentStatus);
  const [isPending, startTransition] = useTransition();

  const onChange = (value: string) => {
    const next = value as OrderStatus;
    const previous = status;
    setStatus(next);
    startTransition(async () => {
      const result = await updateOrderStatus(orderId, next);
      if (!result.success) {
        setStatus(previous);
        toast.error(result.error ?? "Update failed");
      } else {
        toast.success(`Order marked as ${next}`);
      }
    });
  };

  return (
    <Select value={status} onValueChange={onChange} disabled={isPending}>
      <SelectTrigger className="h-9 w-36 capitalize">
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {STATUSES.map((s) => (
          <SelectItem key={s} value={s} className="capitalize">
            {s}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

"use client";

import Image from "next/image";
import { useRouter } from "next/navigation";
import { useState } from "react";

import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, Plus, Trash2, UploadCloud, X } from "lucide-react";
import { Controller, useFieldArray, useForm } from "react-hook-form";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { SIZES } from "@/constants/shop";
import { createProduct, updateProduct } from "@/lib/actions/admin/products";
import { createClient } from "@/lib/supabase/client";
import { slugify } from "@/lib/utils";
import { productSchema, type ProductFormValues } from "@/lib/validators/product";

const BUCKET =
  process.env.NEXT_PUBLIC_SUPABASE_STORAGE_BUCKET ?? "product-images";

interface ProductFormProps {
  categories: { id: string; name: string }[];
  productId?: string;
  defaultValues?: Partial<ProductFormValues>;
}

export function ProductForm({
  categories,
  productId,
  defaultValues,
}: ProductFormProps) {
  const router = useRouter();
  const [uploading, setUploading] = useState(false);

  const {
    register,
    handleSubmit,
    control,
    setValue,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<ProductFormValues>({
    resolver: zodResolver(productSchema),
    defaultValues: {
      title: "",
      slug: "",
      description: "",
      brand_name: "",
      weight: null,
      category_id: null,
      base_price: 0,
      discount_price: null,
      featured: false,
      is_active: true,
      images: [],
      variants: [{ size: "M", stock_quantity: 0 }],
      ...defaultValues,
    },
  });

  const {
    fields: variantFields,
    append,
    remove,
  } = useFieldArray({ control, name: "variants" });

  const images = watch("images");
  const title = watch("title");

  const handleImageUpload = async (files: FileList | null) => {
    if (!files || files.length === 0) return;
    setUploading(true);
    const supabase = createClient();
    const uploaded: string[] = [];

    try {
      for (const file of Array.from(files)) {
        const ext = file.name.split(".").pop();
        const path = `${crypto.randomUUID()}.${ext}`;
        const { error } = await supabase.storage
          .from(BUCKET)
          .upload(path, file, { cacheControl: "3600", upsert: false });
        if (error) throw error;
        const {
          data: { publicUrl },
        } = supabase.storage.from(BUCKET).getPublicUrl(path);
        uploaded.push(publicUrl);
      }
      setValue("images", [...images, ...uploaded], { shouldValidate: true });
      toast.success(`${uploaded.length} image(s) uploaded`);
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Image upload failed"
      );
    } finally {
      setUploading(false);
    }
  };

  const removeImage = (url: string) => {
    setValue(
      "images",
      images.filter((i) => i !== url),
      { shouldValidate: true }
    );
  };

  const onSubmit = async (values: ProductFormValues) => {
    const action = productId
      ? updateProduct(productId, values)
      : createProduct(values);
    const result = await action;

    if (!result.success) {
      toast.error(result.error ?? "Something went wrong");
      return;
    }
    toast.success(productId ? "Product updated" : "Product created");
    router.push("/admin/products");
    router.refresh();
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-10">
      {/* Basic info */}
      <section className="border border-border bg-white p-6">
        <h2 className="mb-6 font-serif text-xl">Product Details</h2>
        <div className="grid gap-5 sm:grid-cols-2">
          <div className="space-y-1.5">
            <Label>Title</Label>
            <Input
              {...register("title")}
              onBlur={(e) => {
                if (!watch("slug")) setValue("slug", slugify(e.target.value));
              }}
              placeholder="Silk Slip Midi Dress"
            />
            {errors.title && (
              <p className="text-xs text-destructive">{errors.title.message}</p>
            )}
          </div>
          <div className="space-y-1.5">
            <Label>Slug</Label>
            <div className="flex gap-2">
              <Input {...register("slug")} placeholder="silk-slip-midi-dress" />
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => setValue("slug", slugify(title))}
              >
                Auto
              </Button>
            </div>
            {errors.slug && (
              <p className="text-xs text-destructive">{errors.slug.message}</p>
            )}
          </div>
          <div className="space-y-1.5 sm:col-span-2">
            <Label>Description</Label>
            <Textarea {...register("description")} rows={4} />
          </div>
          <div className="space-y-1.5">
            <Label>Brand name</Label>
            <Input
              {...register("brand_name")}
              placeholder="e.g. Zara, H&M, Local Brand"
            />
            {errors.brand_name && (
              <p className="text-xs text-destructive">
                {errors.brand_name.message}
              </p>
            )}
          </div>
          <div className="space-y-1.5">
            <Label>Weight (grams)</Label>
            <Input
              type="number"
              step="0.01"
              min={0}
              {...register("weight")}
              placeholder="e.g. 350"
            />
            <p className="text-[11px] text-muted-foreground">
              Used for shipping records. Leave empty if unknown.
            </p>
            {errors.weight && (
              <p className="text-xs text-destructive">{errors.weight.message}</p>
            )}
          </div>
          <div className="space-y-1.5">
            <Label>Category</Label>
            <Controller
              control={control}
              name="category_id"
              render={({ field }) => (
                <Select
                  value={field.value ?? undefined}
                  onValueChange={field.onChange}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select category" />
                  </SelectTrigger>
                  <SelectContent>
                    {categories.map((c) => (
                      <SelectItem key={c.id} value={c.id}>
                        {c.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label>Base price</Label>
              <Input type="number" step="0.01" {...register("base_price")} />
              {errors.base_price && (
                <p className="text-xs text-destructive">
                  {errors.base_price.message}
                </p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label>Discount price</Label>
              <Input
                type="number"
                step="0.01"
                {...register("discount_price")}
                placeholder="Optional"
              />
            </div>
          </div>
        </div>

        <div className="mt-6 flex gap-8">
          <Controller
            control={control}
            name="featured"
            render={({ field }) => (
              <label className="flex items-center gap-2 text-sm">
                <Checkbox
                  checked={field.value}
                  onCheckedChange={field.onChange}
                />
                Featured
              </label>
            )}
          />
          <Controller
            control={control}
            name="is_active"
            render={({ field }) => (
              <label className="flex items-center gap-2 text-sm">
                <Checkbox
                  checked={field.value}
                  onCheckedChange={field.onChange}
                />
                Active (visible in store)
              </label>
            )}
          />
        </div>
      </section>

      {/* Images */}
      <section className="border border-border bg-white p-6">
        <h2 className="mb-6 font-serif text-xl">Images</h2>
        <div className="flex flex-wrap gap-4">
          {images.map((url) => (
            <div key={url} className="relative h-28 w-24 overflow-hidden border border-border">
              <Image src={url} alt="Product image" fill sizes="96px" className="object-cover" />
              <button
                type="button"
                onClick={() => removeImage(url)}
                className="absolute right-1 top-1 flex h-6 w-6 items-center justify-center rounded-full bg-white/90"
              >
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          ))}
          <label className="flex h-28 w-24 cursor-pointer flex-col items-center justify-center gap-2 border border-dashed border-border text-xs text-muted-foreground hover:border-charcoal">
            {uploading ? (
              <Loader2 className="h-5 w-5 animate-spin" />
            ) : (
              <>
                <UploadCloud className="h-5 w-5" />
                Upload
              </>
            )}
            <input
              type="file"
              accept="image/*"
              multiple
              className="hidden"
              disabled={uploading}
              onChange={(e) => handleImageUpload(e.target.files)}
            />
          </label>
        </div>
      </section>

      {/* Variants */}
      <section className="border border-border bg-white p-6">
        <div className="mb-6 flex items-center justify-between">
          <h2 className="font-serif text-xl">Variants</h2>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => append({ size: "M", stock_quantity: 0 })}
          >
            <Plus className="h-4 w-4" /> Add variant
          </Button>
        </div>

        <div className="space-y-4">
          {variantFields.map((field, index) => (
            <div
              key={field.id}
              className="grid grid-cols-2 items-end gap-3 border border-border p-4 sm:grid-cols-4"
            >
              <div className="space-y-1.5">
                <Label className="text-xs">Size</Label>
                <Controller
                  control={control}
                  name={`variants.${index}.size`}
                  render={({ field: f }) => (
                    <Select value={f.value} onValueChange={f.onChange}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {SIZES.map((s) => (
                          <SelectItem key={s} value={s}>
                            {s}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  )}
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs">Stock</Label>
                <Input
                  type="number"
                  {...register(`variants.${index}.stock_quantity`)}
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs">Price override</Label>
                <Input
                  type="number"
                  step="0.01"
                  placeholder="Optional"
                  {...register(`variants.${index}.price_override`)}
                />
              </div>
              <div className="flex items-end">
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  onClick={() => remove(index)}
                  disabled={variantFields.length === 1}
                >
                  <Trash2 className="h-4 w-4 text-destructive" />
                </Button>
              </div>
            </div>
          ))}
        </div>
        {errors.variants && (
          <p className="mt-2 text-xs text-destructive">
            {errors.variants.message ?? "Check variant details"}
          </p>
        )}
      </section>

      <div className="flex justify-end gap-3">
        <Button
          type="button"
          variant="outline"
          onClick={() => router.push("/admin/products")}
        >
          Cancel
        </Button>
        <Button type="submit" disabled={isSubmitting || uploading}>
          {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
          {productId ? "Save changes" : "Create product"}
        </Button>
      </div>
    </form>
  );
}

"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useState } from "react";

import { Loader2 } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { createClient } from "@/lib/supabase/client";

export function AuthForm({ mode }: { mode: "login" | "register" }) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const redirect = searchParams.get("redirect") ?? "/account";
  const [loading, setLoading] = useState(false);
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const supabase = createClient();

    try {
      if (mode === "register") {
        const { error } = await supabase.auth.signUp({
          email,
          password,
          options: { data: { full_name: fullName } },
        });
        if (error) throw error;
        toast.success("Account created", {
          description: "You're all set. Welcome to Naz's Collection.",
        });
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email,
          password,
        });
        if (error) throw error;
      }
      router.push(redirect);
      router.refresh();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Authentication failed"
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container flex min-h-[70vh] items-center justify-center py-16">
      <div className="w-full max-w-md">
        <div className="mb-8 text-center">
          <h1 className="font-serif text-3xl tracking-tight">
            {mode === "login" ? "Welcome back" : "Create your account"}
          </h1>
          <p className="mt-2 text-sm text-muted-foreground">
            {mode === "login"
              ? "Sign in to view your orders and wishlist."
              : "Join for private previews and faster checkout."}
          </p>
        </div>

        <form onSubmit={onSubmit} className="space-y-4">
          {mode === "register" && (
            <div className="space-y-1.5">
              <Label>Full name</Label>
              <Input
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                required
                placeholder="Jane Doe"
              />
            </div>
          )}
          <div className="space-y-1.5">
            <Label>Email</Label>
            <Input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              placeholder="jane@example.com"
            />
          </div>
          <div className="space-y-1.5">
            <Label>Password</Label>
            <Input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              minLength={6}
              placeholder="••••••••"
            />
          </div>
          <Button type="submit" size="lg" className="w-full" disabled={loading}>
            {loading && <Loader2 className="h-4 w-4 animate-spin" />}
            {mode === "login" ? "Sign in" : "Create account"}
          </Button>
        </form>

        <p className="mt-6 text-center text-sm text-muted-foreground">
          {mode === "login" ? (
            <>
              New here?{" "}
              <Link href="/register" className="link-gold underline underline-offset-4">
                Create an account
              </Link>
            </>
          ) : (
            <>
              Already have an account?{" "}
              <Link href="/login" className="link-gold underline underline-offset-4">
                Sign in
              </Link>
            </>
          )}
        </p>
      </div>
    </div>
  );
}

