        <h4 className="mb-4 text-xs uppercase tracking-[0.25em] text-white/80">
          Client Care
        </h4>
        <ul className="space-y-3">
          {helpLinks.map((l) => (
            <li key={l.label}>
              <Link
                href={l.href}
                className="text-sm text-white/60 transition-colors hover:text-gold"
              >
                {l.label}
              </Link>
            </li>
          ))}
        </ul>
