            reserved.
          </p>
          <p className="uppercase tracking-widest">Modern Elegance · 2026</p>
        </div>
      </div>
    </footer>
  );
}

function FooterCol({
  children,
  className = "space-y-4",
  variants,
}: {
  children: React.ReactNode;
  className?: string;
  variants?: Variants;
}) {
  if (!variants) {
    return <div className={className}>{children}</div>;
  }

  return (
    <motion.div className={className} variants={variants}>
      {children}
    </motion.div>
  );
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { Heart, Menu, Search, ShoppingBag, User } from "lucide-react";

import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { cn } from "@/lib/utils";
import { selectItemCount, useCart } from "@/store/cart";
import { useWishlist } from "@/store/wishlist";

interface NavCategory {
  name: string;
  slug: string;
}

export function Header({ categories }: { categories: NavCategory[] }) {
  const router = useRouter();
  const setCartOpen = useCart((s) => s.setOpen);
  const items = useCart((s) => s.items);
  const wishlistItems = useWishlist((s) => s.items);
  const [mounted, setMounted] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [search, setSearch] = useState("");

  useEffect(() => {
    setMounted(true);
    const onScroll = () => setScrolled(window.scrollY > 8);
    onScroll();
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const cartCount = mounted ? selectItemCount(items) : 0;
  const wishlistCount = mounted ? wishlistItems.length : 0;

  const submitSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const q = search.trim();
    router.push(q ? `/shop?search=${encodeURIComponent(q)}` : "/shop");
  };

  return (
    <header
      className={cn(
        "sticky top-0 z-40 w-full border-b transition-all",
        scrolled
          ? "border-border bg-white/85 backdrop-blur-xl"
          : "border-transparent bg-white"
      )}
    >
      <div className="container flex h-16 items-center justify-between gap-4">
        {/* Mobile menu */}
        <div className="flex items-center gap-2 lg:hidden">
          <Sheet>
            <SheetTrigger aria-label="Open menu">
              <Menu className="h-5 w-5" />
            </SheetTrigger>
            <SheetContent side="left" className="w-72 p-6">
              <SheetHeader>
                <SheetTitle>Menu</SheetTitle>
              </SheetHeader>
              <nav className="mt-8 flex flex-col gap-4">
                <Link href="/shop" className="text-sm uppercase tracking-wide">
                  All Products
                </Link>
                {categories.map((c) => (
                  <Link
                    key={c.slug}
                    href={`/shop?category=${c.slug}`}
                    className="text-sm uppercase tracking-wide text-muted-foreground hover:text-charcoal"
                  >
                    {c.name}
                  </Link>
                ))}
              </nav>
            </SheetContent>
          </Sheet>
        </div>

        {/* Left nav (desktop) */}
        <nav className="hidden items-center gap-6 lg:flex">
          <Link href="/shop" className="text-xs uppercase tracking-widest link-gold">
            Shop All
          </Link>
          {categories.slice(0, 4).map((c) => (
            <Link
              key={c.slug}
              href={`/shop?category=${c.slug}`}
              className="text-xs uppercase tracking-widest link-gold"
            >
              {c.name}
            </Link>
          ))}
        </nav>

        {/* Logo */}
        <Link
          href="/"
          className="absolute left-1/2 -translate-x-1/2 font-serif text-xl tracking-[0.2em] text-gold sm:text-2xl"
        >
          NAZ&apos;S
        </Link>

        {/* Right actions */}
        <div className="flex items-center gap-4">
          <form onSubmit={submitSearch} className="hidden items-center md:flex">
            <div className="flex items-center border-b border-border">
              <Search className="h-4 w-4 text-muted-foreground" />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search"
                className="w-28 bg-transparent px-2 py-1 text-sm placeholder:text-muted-foreground focus:outline-none"
              />
            </div>
          </form>

          <Link href="/account" aria-label="Account" className="hidden sm:block">
            <User className="h-5 w-5 transition-colors hover:text-gold" />
          </Link>

          <Link href="/wishlist" aria-label="Wishlist" className="relative">
            <Heart className="h-5 w-5 transition-colors hover:text-gold" />
            {wishlistCount > 0 && (
              <span className="absolute -right-2 -top-2 flex h-4 w-4 items-center justify-center rounded-full bg-gold text-[10px] font-medium text-charcoal">
                {wishlistCount}
              </span>
            )}
          </Link>

          <button
            onClick={() => setCartOpen(true)}
            aria-label="Open cart"
            className="relative"
          >
            <ShoppingBag className="h-5 w-5 transition-colors hover:text-gold" />
            {cartCount > 0 && (
              <span className="absolute -right-2 -top-2 flex h-4 w-4 items-center justify-center rounded-full bg-charcoal text-[10px] font-medium text-white">
                {cartCount}
              </span>
            )}
          </button>
        </div>
      </div>
    </header>
  );
}

"use client";

import { useState } from "react";

import { ArrowRight } from "lucide-react";
import { toast } from "sonner";

export function NewsletterForm() {
  const [email, setEmail] = useState("");

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.includes("@")) {
      toast.error("Please enter a valid email");
      return;
    }
    toast.success("Welcome to the list", {
      description: "You'll be the first to know about new arrivals.",
    });
    setEmail("");
  };

  return (
    <form onSubmit={onSubmit} className="flex items-center border-b border-white/30">
      <input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="Email address"
        className="w-full bg-transparent py-2 text-sm text-white placeholder:text-white/50 focus:outline-none"
      />
      <button type="submit" aria-label="Subscribe" className="text-gold hover:text-white">
        <ArrowRight className="h-5 w-5" />
      </button>
    </form>
  );
}

"use client";

import { motion, useReducedMotion, type Variants } from "framer-motion";

interface BlurFadeProps {
  children: React.ReactNode;
  className?: string;
  delay?: number;
  duration?: number;
  yOffset?: number;
  inView?: boolean;
}

/**
 * Blur-fade entrance inspired by 21st.dev / Magic UI Blur Fade.
 * Soft blur → crisp focus with a light upward drift.
 */
export function BlurFade({
  children,
  className,
  delay = 0,
  duration = 0.55,
  yOffset = 12,
  inView = true,
}: BlurFadeProps) {
  const reduceMotion = useReducedMotion();

  if (reduceMotion) {
    return <div className={className}>{children}</div>;
  }

  const variants: Variants = {
    hidden: { opacity: 0, y: yOffset, filter: "blur(8px)" },
    visible: {
      opacity: 1,
      y: 0,
      filter: "blur(0px)",
      transition: {
        delay,
        duration,
        ease: [0.22, 1, 0.36, 1],
      },
    },
  };

  return (
    <motion.div
      className={className}
      initial="hidden"
      {...(inView
        ? {
            whileInView: "visible",
            viewport: { once: true, amount: 0.2, margin: "-40px" },
          }
        : { animate: "visible" })}
      variants={variants}
    >
      {children}
    </motion.div>
  );
}

"use client";

import { motion, useReducedMotion, type Variants } from "framer-motion";

type Direction = "up" | "down" | "left" | "right" | "none";

interface RevealProps {
  children: React.ReactNode;
  delay?: number;
  y?: number;
  className?: string;
  /** Stagger index when used as a child of StaggerReveal */
  index?: number;
  direction?: Direction;
  blur?: boolean;
  duration?: number;
}

function offsetFor(direction: Direction, distance: number) {
  switch (direction) {
    case "up":
      return { x: 0, y: distance };
    case "down":
      return { x: 0, y: -distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: 0 };
  }
}

/**
 * Scroll reveal inspired by 21st.dev Reveal —
 * fades, un-blurs, and slides content into view.
 */
export function Reveal({
  children,
  delay = 0,
  y = 28,
  className,
  index,
  direction = "up",
  blur = true,
  duration = 0.7,
}: RevealProps) {
  const reduceMotion = useReducedMotion();
  const offset = offsetFor(direction, y);
  const staggerDelay = typeof index === "number" ? index * 0.08 : 0;

  if (reduceMotion) {
    return <div className={className}>{children}</div>;
  }

  const variants: Variants = {
    hidden: {
      opacity: 0,
      x: offset.x,
      y: offset.y,
      filter: blur ? "blur(8px)" : "blur(0px)",
    },
    show: {
      opacity: 1,
      x: 0,
      y: 0,
      filter: "blur(0px)",
      transition: {
        duration,
        delay: delay + staggerDelay,
        ease: [0.22, 1, 0.36, 1],
      },
    },
  };

  return (
    <motion.div
      variants={variants}
      initial="hidden"
      whileInView="show"
      viewport={{ once: true, amount: 0.2, margin: "-40px" }}
      className={className}
    >
      {children}
    </motion.div>
  );
}

"use client";

import { motion, useReducedMotion, type Variants } from "framer-motion";

import { cn } from "@/lib/utils";

interface StaggerRevealProps {
  children: React.ReactNode;
  className?: string;
  /** Delay between each child (seconds) */
  stagger?: number;
  /** Initial vertical offset */
  fromY?: number;
  duration?: number;
}

/**
 * Staggered grid/list reveal adapted from 21st.dev Stagger Reveal Grid,
 * implemented with Framer Motion (no GSAP dependency).
 */
export function StaggerReveal({
  children,
  className,
  stagger = 0.08,
  fromY = 36,
  duration = 0.55,
}: StaggerRevealProps) {
  const reduceMotion = useReducedMotion();

  if (reduceMotion) {
    return <div className={className}>{children}</div>;
  }

  const container: Variants = {
    hidden: {},
    show: {
      transition: {
        staggerChildren: stagger,
        delayChildren: 0.05,
      },
    },
  };

  const item: Variants = {
    hidden: {
      opacity: 0,
      y: fromY,
      scale: 0.96,
      filter: "blur(6px)",
    },
    show: {
      opacity: 1,
      y: 0,
      scale: 1,
      filter: "blur(0px)",
      transition: {
        duration,
        ease: [0.22, 1, 0.36, 1],
      },
    },
  };

  return (
    <motion.div
      className={cn(className)}
      variants={container}
      initial="hidden"
      whileInView="show"
      viewport={{ once: true, amount: 0.12, margin: "-60px" }}
    >
      {Array.isArray(children)
        ? children.map((child, i) => (
            <motion.div key={i} variants={item}>
              {child}
            </motion.div>
          ))
        : children}
    </motion.div>
  );
}

/** Wrap a single grid item when mapping outside StaggerReveal's children array. */
export function StaggerItem({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  const reduceMotion = useReducedMotion();

  if (reduceMotion) {
    return <div className={className}>{children}</div>;
  }

  return (
    <motion.div
      className={className}
      variants={{
        hidden: {
          opacity: 0,
          y: 36,
          scale: 0.96,
          filter: "blur(6px)",
        },
        show: {
          opacity: 1,
          y: 0,
          scale: 1,
          filter: "blur(0px)",
          transition: {
            duration: 0.55,
            ease: [0.22, 1, 0.36, 1],
          },
        },
      }}
    >
      {children}
    </motion.div>
  );
}

"use client";

import { useEffect } from "react";

import confetti from "canvas-confetti";

/**
 * Fires a party-boom confetti celebration once when the order
 * confirmation page mounts.
 */
export function OrderCelebration() {
  useEffect(() => {
    const duration = 2800;
    const end = Date.now() + duration;

    const frame = () => {
      confetti({
        particleCount: 4,
        angle: 60,
        spread: 60,
        origin: { x: 0, y: 0.7 },
        colors: ["#D4AF37", "#121212", "#C0C0C0", "#FFFFFF"],
      });
      confetti({
        particleCount: 4,
        angle: 120,
        spread: 60,
        origin: { x: 1, y: 0.7 },
        colors: ["#D4AF37", "#121212", "#C0C0C0", "#FFFFFF"],
      });

      if (Date.now() < end) {
        requestAnimationFrame(frame);
      }
    };

    // Big initial boom
    confetti({
      particleCount: 120,
      spread: 90,
      startVelocity: 45,
      origin: { y: 0.55 },
      colors: ["#D4AF37", "#121212", "#C0C0C0", "#E4C766", "#FFFFFF"],
    });

    const raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, []);

  return null;
}

import { cn, formatPrice } from "@/lib/utils";

interface PriceProps {
  basePrice: number;
  discountPrice?: number | null;
  className?: string;
  size?: "sm" | "md" | "lg";
}

const sizeMap = {
  sm: "text-sm",
  md: "text-base",
  lg: "text-xl",
};

export function Price({
  basePrice,
  discountPrice,
  className,
  size = "md",
}: PriceProps) {
  const hasDiscount =
    typeof discountPrice === "number" && discountPrice < basePrice;

  return (
    <div className={cn("flex items-baseline gap-2", sizeMap[size], className)}>
      <span
        className={cn(
          "font-medium",
          hasDiscount ? "text-gold-dark" : "text-charcoal"
        )}
      >
        {formatPrice(hasDiscount ? discountPrice! : basePrice)}
      </span>
      {hasDiscount && (
        <span className="text-muted-foreground line-through">
          {formatPrice(basePrice)}
        </span>
      )}
    </div>
  );
}

"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";

import { motion, useReducedMotion } from "framer-motion";
import { Heart, ShoppingBag } from "lucide-react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Price } from "@/components/product/price";
import { cn } from "@/lib/utils";
import type { ProductCardData } from "@/lib/types";
import { useCart } from "@/store/cart";
import { useWishlist } from "@/store/wishlist";

interface ProductCardProps {
  product: ProductCardData;
  priority?: boolean;
}

export function ProductCard({ product, priority = false }: ProductCardProps) {
  const [hovered, setHovered] = useState(false);
  const reduceMotion = useReducedMotion();
  const addItem = useCart((s) => s.addItem);
  const toggleWishlist = useWishlist((s) => s.toggle);
  const inWishlist = useWishlist((s) =>
    s.items.some((i) => i.productId === product.id)
  );

  const images = [...product.images].sort(
    (a, b) => a.display_order - b.display_order
  );
  const primary = images[0]?.image_url ?? null;
  const secondary = images[1]?.image_url ?? primary;

  const effectivePrice = product.discount_price ?? product.base_price;

  const firstAvailable = product.variants.find((v) => v.stock_quantity > 0);
  const soldOut = !firstAvailable;

  const handleQuickAdd = () => {
    if (!firstAvailable) return;
    addItem({
      variantId: firstAvailable.id,
      productId: product.id,
      slug: product.slug,
      title: product.title,
      image: primary,
      size: firstAvailable.size,
      unitPrice: firstAvailable.price_override ?? effectivePrice,
      maxStock: firstAvailable.stock_quantity,
    });
    toast.success("Added to bag", {
      description: `${product.title} — Size ${firstAvailable.size}`,
    });
  };

  return (
    <motion.div
      className="group relative flex flex-col"
      whileHover={reduceMotion ? undefined : { y: -4 }}
      transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
    >
      <div
        className="relative aspect-[3/4] overflow-hidden bg-muted"
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
      >
        <Link href={`/product/${product.slug}`} className="block h-full w-full">
          {primary ? (
            <motion.div
              className="absolute inset-0"
              animate={
                reduceMotion
                  ? undefined
                  : { scale: hovered ? 1.05 : 1 }
              }
              transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
            >
              <Image
                src={primary}
                alt={product.title}
                fill
                sizes="(max-width: 768px) 50vw, 25vw"
                priority={priority}
                className={cn(
                  "object-cover transition-opacity duration-700",
                  hovered && secondary !== primary ? "opacity-0" : "opacity-100"
                )}
              />
              {secondary && secondary !== primary && (
                <Image
                  src={secondary}
                  alt={`${product.title} alternate view`}
                  fill
                  sizes="(max-width: 768px) 50vw, 25vw"
                  className={cn(
                    "object-cover transition-opacity duration-700",
                    hovered ? "opacity-100" : "opacity-0"
                  )}
                />
              )}
            </motion.div>
          ) : (
            <div className="flex h-full items-center justify-center text-muted-foreground">
              No image
            </div>
          )}
        </Link>

        <div className="absolute left-3 top-3 flex flex-col gap-2">
          {product.discount_price && (
            <Badge variant="gold">Sale</Badge>
          )}
          {soldOut && <Badge variant="muted">Sold out</Badge>}
        </div>

        <button
          type="button"
          aria-label="Toggle wishlist"
          onClick={() =>
            toggleWishlist({
              productId: product.id,
              slug: product.slug,
              title: product.title,
              image: primary,
              price: effectivePrice,
            })
          }
          className="absolute right-3 top-3 flex h-9 w-9 items-center justify-center rounded-full bg-white/80 backdrop-blur transition-colors hover:bg-white"
        >
          <Heart
            className={cn(
              "h-4 w-4",
              inWishlist ? "fill-gold text-gold" : "text-charcoal"
            )}
          />
        </button>

        {!soldOut && (
          <button
            type="button"
            onClick={handleQuickAdd}
            className="absolute inset-x-3 bottom-3 flex translate-y-3 items-center justify-center gap-2 bg-charcoal py-3 text-xs font-medium uppercase tracking-widest text-white opacity-0 transition-all duration-300 hover:bg-gold hover:text-charcoal group-hover:translate-y-0 group-hover:opacity-100"
          >
            <ShoppingBag className="h-4 w-4" /> Quick add
          </button>
        )}
      </div>

      <div className="mt-4 flex flex-col gap-1.5">
        {product.brand_name && (
          <span className="text-[11px] uppercase tracking-widest text-muted-foreground">
            {product.brand_name}
          </span>
        )}
        <Link href={`/product/${product.slug}`}>
          <h3 className="font-sans text-sm font-medium tracking-wide text-charcoal transition-colors group-hover:text-gold">
            {product.title}
          </h3>
        </Link>
        <Price
          basePrice={product.base_price}
          discountPrice={product.discount_price}
          size="sm"
        />
      </div>
    </motion.div>
  );
}

"use client";

import Image from "next/image";
import { useMemo, useState } from "react";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Heart, Minus, Plus, Ruler, ShoppingBag } from "lucide-react";
import { toast } from "sonner";

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { BlurFade } from "@/components/motion/blur-fade";
import { Price } from "@/components/product/price";
import { SizeSelector } from "@/components/product/size-selector";
import { cn } from "@/lib/utils";
import type { ProductWithRelations } from "@/lib/types";
import { useCart } from "@/store/cart";
import { useWishlist } from "@/store/wishlist";

export function ProductDetail({ product }: { product: ProductWithRelations }) {
  const reduceMotion = useReducedMotion();
  const addItem = useCart((s) => s.addItem);
  const toggleWishlist = useWishlist((s) => s.toggle);
  const inWishlist = useWishlist((s) =>
    s.items.some((i) => i.productId === product.id)
  );

  const images = product.images.length
    ? product.images
    : [{ id: "placeholder", image_url: "", display_order: 0, product_id: product.id }];

  const [activeImage, setActiveImage] = useState(0);

  const [selectedSize, setSelectedSize] = useState<string | undefined>();
  const [quantity, setQuantity] = useState(1);

  const sizeOptions = useMemo(() => {
    const list = product.variants.map((v) => ({
      size: v.size,
      disabled: v.stock_quantity <= 0,
    }));
    return Array.from(new Map(list.map((s) => [s.size, s])).values());
  }, [product.variants]);

  const selectedVariant = useMemo(
    () => product.variants.find((v) => v.size === selectedSize),
    [product.variants, selectedSize]
  );

  const effectivePrice = product.discount_price ?? product.base_price;
  const displayPrice = selectedVariant?.price_override ?? effectivePrice;
  const maxStock = selectedVariant?.stock_quantity ?? 0;

  const handleAddToBag = () => {
    if (!selectedSize) {
      toast.error("Please select a size");
      return;
    }
    if (!selectedVariant || maxStock <= 0) {
      toast.error("This selection is out of stock");
      return;
    }
    addItem(
      {
        variantId: selectedVariant.id,
        productId: product.id,
        slug: product.slug,
        title: product.title,
        image: images[0].image_url || null,
        size: selectedVariant.size,
        unitPrice: displayPrice,
        maxStock,
      },
      quantity
    );
    toast.success("Added to bag", {
      description: `${product.title} — Size ${selectedVariant.size}`,
    });
  };

  return (
    <div className="container max-w-full overflow-x-hidden py-10">
      <div className="grid w-full min-w-0 gap-10 lg:grid-cols-2">
        {/* Gallery */}
        <motion.div
          className="flex w-full min-w-0 flex-col gap-4"
          initial={reduceMotion ? false : { opacity: 0, x: -24 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
        >
          <div className="relative aspect-[3/4] w-full overflow-hidden bg-muted">
            <AnimatePresence mode="wait">
              {images[activeImage].image_url ? (
                <motion.div
                  key={images[activeImage].id}
                  className="absolute inset-0"
                  initial={
                    reduceMotion
                      ? false
                      : { opacity: 0, scale: 1.02, filter: "blur(4px)" }
                  }
                  animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
                  exit={
                    reduceMotion
                      ? undefined
                      : { opacity: 0, scale: 0.99, filter: "blur(4px)" }
                  }
                  transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}
                >
                  <Image
                    src={images[activeImage].image_url}
                    alt={product.title}
                    fill
                    priority
                    sizes="(max-width: 1024px) 100vw, 50vw"
                    className="object-contain"
                  />
                </motion.div>
              ) : (
                <div className="flex h-full items-center justify-center text-muted-foreground">
                  No image
                </div>
              )}
            </AnimatePresence>
          </div>
          {images.length > 1 && (
            <div className="flex w-full gap-3 overflow-x-auto pb-1">
              {images.map((img, i) => (
                <button
                  key={img.id}
                  onClick={() => setActiveImage(i)}
                  className={cn(
                    "relative h-20 w-16 shrink-0 overflow-hidden border",
                    activeImage === i ? "border-charcoal" : "border-transparent"
                  )}
                >
                  {img.image_url && (
                    <Image
                      src={img.image_url}
                      alt={`${product.title} view ${i + 1}`}
                      fill
                      sizes="64px"
                      className="object-cover"
                    />
                  )}
                </button>
              ))}
            </div>
          )}
        </motion.div>

        {/* Details */}
        <BlurFade className="min-w-0 w-full lg:py-4" delay={0.1} inView={false}>
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
            {product.brand_name && (
              <span className="eyebrow text-gold">{product.brand_name}</span>
            )}
            {product.category && (
              <span className="eyebrow">{product.category.name}</span>
            )}
          </div>
          <h1 className="mt-2 font-serif text-3xl tracking-tight sm:text-4xl">
            {product.title}
          </h1>
          <Price
            basePrice={product.base_price}
            discountPrice={product.discount_price}
            size="lg"
            className="mt-4"
          />

          <p className="mt-6 text-sm leading-relaxed text-muted-foreground">
            {product.description}
          </p>

          {product.weight != null && (
            <p className="mt-3 text-xs text-muted-foreground">
              Weight: {Number(product.weight)} g
            </p>
          )}

          {/* Size */}
          <div className="mt-8">
            <div className="mb-3 flex items-center justify-between">
              <span className="text-sm font-medium">Size</span>
              <Dialog>
                <DialogTrigger className="flex items-center gap-1 text-xs uppercase tracking-wide text-muted-foreground hover:text-charcoal">
                  <Ruler className="h-3.5 w-3.5" /> Size Guide
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle>Size Guide</DialogTitle>
                  </DialogHeader>
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-border text-left">
                        <th className="py-2">Size</th>
                        <th className="py-2">Bust (in)</th>
                        <th className="py-2">Waist (in)</th>
                        <th className="py-2">Hips (in)</th>
                      </tr>
                    </thead>
                    <tbody className="text-muted-foreground">
                      {[
                        ["XS", "31-32", "24-25", "34-35"],
                        ["S", "33-34", "26-27", "36-37"],
                        ["M", "35-36", "28-29", "38-39"],
                        ["L", "37-39", "30-32", "40-42"],
                        ["XL", "40-42", "33-35", "43-45"],
                      ].map((row) => (
                        <tr key={row[0]} className="border-b border-border">
                          {row.map((cell, i) => (
                            <td key={i} className="py-2">
                              {cell}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </DialogContent>
              </Dialog>
            </div>
            <SizeSelector
              options={sizeOptions}
              selected={selectedSize}
              onSelect={setSelectedSize}
            />
          </div>

          {/* Quantity + Add to bag */}
          <div className="mt-8 flex w-full min-w-0 flex-wrap items-stretch gap-3">
            <div className="flex h-14 shrink-0 items-center border border-charcoal/20">
              <button
                className="flex h-full w-11 items-center justify-center transition-colors hover:bg-muted"
                onClick={() => setQuantity((q) => Math.max(1, q - 1))}
                aria-label="Decrease quantity"
              >
                <Minus className="h-3.5 w-3.5" />
              </button>
              <span className="w-8 text-center text-sm font-medium tracking-wide">
                {quantity}
              </span>
              <button
                className="flex h-full w-11 items-center justify-center transition-colors hover:bg-muted disabled:opacity-40"
                disabled={maxStock > 0 && quantity >= maxStock}
                onClick={() => setQuantity((q) => q + 1)}
                aria-label="Increase quantity"
              >
                <Plus className="h-3.5 w-3.5" />
              </button>
            </div>
            <Button
              size="lg"
              className="group relative min-w-0 flex-1 overflow-hidden border border-charcoal bg-charcoal text-xs font-medium uppercase tracking-[0.22em] text-white transition-all duration-500 hover:border-gold hover:bg-gold hover:text-charcoal disabled:border-border disabled:bg-muted disabled:text-muted-foreground"
              onClick={handleAddToBag}
              disabled={selectedVariant ? maxStock <= 0 : false}
            >
              <ShoppingBag className="h-4 w-4 transition-transform duration-500 group-hover:-translate-y-0.5" />
              {selectedVariant && maxStock <= 0 ? "Out of stock" : "Add to Bag"}
            </Button>
            <Button
              variant="outline"
              size="icon"
              className="h-14 w-14 shrink-0 border-charcoal/20 transition-colors duration-300 hover:border-gold hover:text-gold"
              aria-label="Add to wishlist"
              onClick={() =>
                toggleWishlist({
                  productId: product.id,
                  slug: product.slug,
                  title: product.title,
                  image: images[0].image_url || null,
                  price: effectivePrice,
                })
              }
            >
              <Heart
                className={cn("h-5 w-5", inWishlist && "fill-gold text-gold")}
              />
            </Button>
          </div>

          {selectedVariant && maxStock > 0 && maxStock <= 3 && (
            <p className="mt-3 text-xs text-gold-dark">
              Only {maxStock} left — order soon
            </p>
          )}

          {/* Accordions */}
          <Accordion type="single" collapsible className="mt-10">
            <AccordionItem value="fabric">
              <AccordionTrigger>Fabric &amp; Details</AccordionTrigger>
              <AccordionContent>
                Crafted from premium, responsibly sourced materials. Each piece
                is finished by hand for an impeccable drape and lasting quality.
              </AccordionContent>
            </AccordionItem>
            <AccordionItem value="shipping">
              <AccordionTrigger>Shipping &amp; Returns</AccordionTrigger>
              <AccordionContent>
                Complimentary shipping on orders over $150. Free 30-day returns
                on all unworn items with tags attached.
              </AccordionContent>
            </AccordionItem>
            <AccordionItem value="care">
              <AccordionTrigger>Care Instructions</AccordionTrigger>
              <AccordionContent>
                Dry clean only or hand wash cold. Lay flat to dry. Cool iron if
                needed. Store on a padded hanger to preserve shape.
              </AccordionContent>
            </AccordionItem>
          </Accordion>
        </BlurFade>
      </div>
    </div>
  );
}

"use client";

import { motion, useReducedMotion, type Variants } from "framer-motion";

import { ProductCard } from "@/components/product/product-card";
import { cn } from "@/lib/utils";
import type { ProductCardData } from "@/lib/types";

interface ProductGridProps {
  products: ProductCardData[];
  className?: string;
  emptyMessage?: string;
}

export function ProductGrid({
  products,
  className,
  emptyMessage = "No products found.",
}: ProductGridProps) {
  const reduceMotion = useReducedMotion();

  if (products.length === 0) {
    return (
      <div className="flex min-h-[240px] items-center justify-center text-sm text-muted-foreground">
        {emptyMessage}
      </div>
    );
  }

  const container: Variants = {
    hidden: {},
    show: {
      transition: { staggerChildren: 0.07, delayChildren: 0.04 },
    },
  };

  const item: Variants = {
    hidden: {
      opacity: 0,
      y: 32,
      scale: 0.97,
      filter: "blur(6px)",
    },
    show: {
      opacity: 1,
      y: 0,
      scale: 1,
      filter: "blur(0px)",
      transition: { duration: 0.55, ease: [0.22, 1, 0.36, 1] },
    },
  };

  if (reduceMotion) {
    return (
      <div
        className={cn(
          "grid grid-cols-2 gap-x-4 gap-y-10 md:grid-cols-3 lg:grid-cols-4",
          className
        )}
      >
        {products.map((product, i) => (
          <ProductCard key={product.id} product={product} priority={i < 4} />
        ))}
      </div>
    );
  }

  return (
    <motion.div
      className={cn(
        "grid grid-cols-2 gap-x-4 gap-y-10 md:grid-cols-3 lg:grid-cols-4",
        className
      )}
      variants={container}
      initial="hidden"
      whileInView="show"
      viewport={{ once: true, amount: 0.1, margin: "-40px" }}
    >
      {products.map((product, i) => (
        <motion.div key={product.id} variants={item}>
          <ProductCard product={product} priority={i < 4} />
        </motion.div>
      ))}
    </motion.div>
  );
}

