import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Format a numeric amount as PKR currency. */
export function formatPrice(
  amount: number,
  options: Intl.NumberFormatOptions = {}
) {
  return new Intl.NumberFormat("en-PK", {
    style: "currency",
    currency: "PKR",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
    ...options,
  }).format(amount);
}

/** Convert an arbitrary string into a URL-safe slug. */
export function slugify(value: string) {
  return value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");
}

/** Generate a human-friendly, unique-ish order number. */
export function generateOrderNumber() {
  const now = new Date();
  const stamp = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(
    2,
    "0"
  )}${String(now.getDate()).padStart(2, "0")}`;
  const random = Math.floor(1000 + Math.random() * 9000);
  return `NAZ-${stamp}-${random}`;
}

import { z } from "zod";

const checkoutFields = {
  customerName: z.string().min(2, "Please enter your full name"),
  customerEmail: z.string().email("Enter a valid email address"),
  customerPhone: z
    .string()
    .min(7, "Enter a valid phone number")
    .max(20, "Phone number is too long"),
  address: z.string().min(4, "Enter your street address"),
  /** Delivery city — drives shipping (Karachi 350 / other 400). */
  city: z.string().min(2, "Please select your city"),
  /** Used when city = "Other" */
  cityOther: z.string().optional().nullable(),
  postalCode: z.string().min(3, "Enter your postal code"),
  country: z.string().min(2, "Enter your country"),
  paymentMethod: z.enum(["COD", "Card"]),
};

function refineCityOther(
  data: { city: string; cityOther?: string | null },
  ctx: z.RefinementCtx
) {
  if (
    data.city === "Other" &&
    (!data.cityOther || data.cityOther.trim().length < 2)
  ) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: "Please enter your city name",
      path: ["cityOther"],
    });
  }
}

export const checkoutSchema = z
  .object(checkoutFields)
  .superRefine(refineCityOther);

export type CheckoutFormValues = z.infer<typeof checkoutSchema>;

export const orderItemSchema = z.object({
  variantId: z.string().uuid(),
  quantity: z.number().int().positive(),
});

export const placeOrderSchema = z
  .object({
    ...checkoutFields,
    items: z.array(orderItemSchema).min(1, "Your bag is empty"),
  })
  .superRefine(refineCityOther);

export type PlaceOrderInput = z.infer<typeof placeOrderSchema>;

import { z } from "zod";

export const variantSchema = z.object({
  size: z.enum(["XS", "S", "M", "L", "XL", "Custom"]),
  stock_quantity: z.coerce.number().int().min(0),
  price_override: z.coerce.number().min(0).optional().nullable(),
});

export const productSchema = z.object({
  title: z.string().min(2, "Title is required"),
  slug: z.string().min(2, "Slug is required"),
  description: z.string().optional().nullable(),
  brand_name: z.string().min(1, "Brand name is required").max(120),
  /** Weight in grams — empty input becomes null */
  weight: z.preprocess((val) => {
    if (val === "" || val === null || val === undefined) return null;
    const n = typeof val === "number" ? val : Number(val);
    return Number.isNaN(n) ? null : n;
  }, z.number().min(0, "Weight must be 0 or more").nullable()),
  category_id: z.string().uuid().optional().nullable(),
  base_price: z.coerce.number().min(0, "Price must be positive"),
  discount_price: z.coerce.number().min(0).optional().nullable(),
  featured: z.boolean().default(false),
  is_active: z.boolean().default(true),
  images: z.array(z.string().url()).default([]),
  variants: z.array(variantSchema).min(1, "Add at least one variant"),
});

export type ProductFormValues = z.infer<typeof productSchema>;
export type VariantFormValues = z.infer<typeof variantSchema>;

